from collections.abc import Callable
from pathlib import Path
from types import ModuleType

import pytest

from risk import VolSeries, vol_pipeline, vol_series


@pytest.fixture
def fake_prices(
    monkeypatch: pytest.MonkeyPatch, contract_fake: Callable[[str], ModuleType]
) -> None:
    fake = contract_fake("mdata.load_prices")
    monkeypatch.setattr(vol_pipeline, "load_prices", fake.load_prices)


@pytest.mark.usefixtures("fake_prices")
def test_pl02_runs_end_to_end_and_returns_aligned_shape() -> None:
    vol = vol_series(Path("unused.csv"), window=2)
    assert isinstance(vol, VolSeries)
    assert vol.window == 2
    assert vol.returns.tickers == ("AAA", "BBB")
    assert set(vol.values) == {"AAA", "BBB"}
    assert len(vol.returns.dates) == 5
    assert all(len(vol.values[t]) == len(vol.returns.dates) for t in vol.returns.tickers)


@pytest.mark.usefixtures("fake_prices")
def test_pl02_ticker_filter_and_default_window_reach_the_output() -> None:
    vol = vol_series("unused.csv", tickers=["BBB"])
    assert vol.window == 20
    assert vol.returns.tickers == ("BBB",)
    assert set(vol.values) == {"BBB"}
    assert len(vol.values["BBB"]) == len(vol.returns.dates)

